CREATE TABLE IF NOT EXISTS depth_updates (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, first_update_id UBIGINT, final_update_id UBIGINT, source VARCHAR);
CREATE TABLE IF NOT EXISTS depth_levels (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, first_update_id UBIGINT, final_update_id UBIGINT, side VARCHAR, level INTEGER, price DECIMAL(38,18), quantity DECIMAL(38,18), source VARCHAR);
CREATE TABLE IF NOT EXISTS aggregate_trades (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, aggregate_trade_id UBIGINT, price DECIMAL(38,18), quantity DECIMAL(38,18), first_trade_id UBIGINT, last_trade_id UBIGINT, trade_time TIMESTAMPTZ, buyer_is_maker BOOLEAN, is_best_match BOOLEAN, source VARCHAR);
CREATE TABLE IF NOT EXISTS trades (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, trade_id UBIGINT, price DECIMAL(38,18), quantity DECIMAL(38,18), trade_time TIMESTAMPTZ, buyer_is_maker BOOLEAN, is_best_match BOOLEAN, source VARCHAR);
CREATE TABLE IF NOT EXISTS book_tickers (received_at TIMESTAMPTZ, symbol VARCHAR, update_id UBIGINT, bid_price DECIMAL(38,18), bid_quantity DECIMAL(38,18), ask_price DECIMAL(38,18), ask_quantity DECIMAL(38,18), source VARCHAR);
CREATE TABLE IF NOT EXISTS tickers (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, price_change DECIMAL(38,18), price_change_percent DECIMAL(38,18), weighted_average_price DECIMAL(38,18), previous_close_price DECIMAL(38,18), last_price DECIMAL(38,18), last_quantity DECIMAL(38,18), bid_price DECIMAL(38,18), bid_quantity DECIMAL(38,18), ask_price DECIMAL(38,18), ask_quantity DECIMAL(38,18), open_price DECIMAL(38,18), high_price DECIMAL(38,18), low_price DECIMAL(38,18), base_volume DECIMAL(38,18), quote_volume DECIMAL(38,18), statistics_open_time TIMESTAMPTZ, statistics_close_time TIMESTAMPTZ, first_trade_id BIGINT, last_trade_id BIGINT, trade_count UBIGINT, source VARCHAR);
CREATE TABLE IF NOT EXISTS rolling_tickers (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, window_size VARCHAR, price_change DECIMAL(38,18), price_change_percent DECIMAL(38,18), open_price DECIMAL(38,18), high_price DECIMAL(38,18), low_price DECIMAL(38,18), last_price DECIMAL(38,18), weighted_average_price DECIMAL(38,18), base_volume DECIMAL(38,18), quote_volume DECIMAL(38,18), statistics_open_time TIMESTAMPTZ, statistics_close_time TIMESTAMPTZ, first_trade_id BIGINT, last_trade_id BIGINT, trade_count UBIGINT, source VARCHAR);
CREATE TABLE IF NOT EXISTS mini_tickers (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, close_price DECIMAL(38,18), open_price DECIMAL(38,18), high_price DECIMAL(38,18), low_price DECIMAL(38,18), base_volume DECIMAL(38,18), quote_volume DECIMAL(38,18), source VARCHAR);
CREATE TABLE IF NOT EXISTS klines (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, kline_start_time TIMESTAMPTZ, kline_close_time TIMESTAMPTZ, kline_symbol VARCHAR, interval VARCHAR, first_trade_id BIGINT, last_trade_id BIGINT, open_price DECIMAL(38,18), close_price DECIMAL(38,18), high_price DECIMAL(38,18), low_price DECIMAL(38,18), base_volume DECIMAL(38,18), trade_count UBIGINT, is_closed BOOLEAN, quote_volume DECIMAL(38,18), taker_buy_base_volume DECIMAL(38,18), taker_buy_quote_volume DECIMAL(38,18), ignored DECIMAL(38,18), source VARCHAR);
CREATE TABLE IF NOT EXISTS average_prices (event_time TIMESTAMPTZ, received_at TIMESTAMPTZ, symbol VARCHAR, interval VARCHAR, average_price DECIMAL(38,18), last_trade_time TIMESTAMPTZ, source VARCHAR);
CREATE TABLE IF NOT EXISTS parquet_exports (table_name VARCHAR, hour_start TIMESTAMPTZ, exported_at TIMESTAMPTZ, PRIMARY KEY (table_name, hour_start));
CREATE TABLE IF NOT EXISTS integrity_issues (detected_at TIMESTAMPTZ, hour_start TIMESTAMPTZ, symbol VARCHAR, data_type VARCHAR, first_missing_id UBIGINT, last_missing_id UBIGINT, status VARCHAR, detail VARCHAR);
CREATE TABLE IF NOT EXISTS parquet_uploads (table_name VARCHAR, hour_start TIMESTAMPTZ, bucket VARCHAR, object_key VARCHAR, etag VARCHAR, size_bytes UBIGINT, uploaded_at TIMESTAMPTZ, PRIMARY KEY (table_name, hour_start, bucket));
CREATE TABLE IF NOT EXISTS parquet_symbol_exports (table_name VARCHAR, symbol VARCHAR, hour_start TIMESTAMPTZ, exported_at TIMESTAMPTZ, PRIMARY KEY (table_name, symbol, hour_start));
CREATE TABLE IF NOT EXISTS parquet_symbol_uploads (table_name VARCHAR, symbol VARCHAR, hour_start TIMESTAMPTZ, bucket VARCHAR, object_key VARCHAR, etag VARCHAR, size_bytes UBIGINT, uploaded_at TIMESTAMPTZ, PRIMARY KEY (table_name, symbol, hour_start, bucket));
